#include <iostream>
#include <string>

// User-defined type illustrating Software Engineering Observation 13.2
struct Measurement {
    std::string unit;
    double magnitude{0.0};
};

// Extensibility: Overload stream extraction operator >>
std::istream& operator>>(std::istream& in, Measurement& m) {
    in >> m.unit >> m.magnitude;
    return in;
}

// Extensibility: Overload stream insertion operator <<
std::ostream& operator<<(std::ostream& out, const Measurement& m) {
    out << m.magnitude << " [" << m.unit << "]";
    return out;
}

int main() {
    int sensorId{0};
    Measurement reading;

    // Input operation is strictly type-safe at compile time
    if (std::cin >> sensorId >> reading) {
        std::cout << "Sensor ID: " << sensorId
                  << ", Reading: " << reading << '\n';
    }

    return 0;
}

#include <iostream>
#include <type_traits>

int main() {
    // Section 13.2.1: Character types and memory footprint in modern C++
    std::cout << "sizeof(char): " << sizeof(char) << " byte\n";
    std::cout << "sizeof(char16_t): " << sizeof(char16_t) << " bytes\n";
    std::cout << "sizeof(char32_t): " << sizeof(char32_t) << " bytes\n";

    // Section 13.2.3: Verification of typedef aliases for template specializations
    static_assert(std::is_same_v<std::istream, std::basic_istream<char>>,
                  "std::istream must be an alias for basic_istream<char>");
    static_assert(std::is_same_v<std::ostream, std::basic_ostream<char>>,
                  "std::ostream must be an alias for basic_ostream<char>");
    static_assert(std::is_same_v<std::iostream, std::basic_iostream<char>>,
                  "std::iostream must be an alias for basic_iostream<char>");

    // Demonstrating the multiple inheritance relationship:
    // basic_iostream derives from both basic_istream and basic_ostream
    static_assert(std::is_base_of_v<std::istream, std::iostream>,
                  "iostream must derive from istream");
    static_assert(std::is_base_of_v<std::ostream, std::iostream>,
                  "iostream must derive from ostream");

    // High-level formatted output: grouping bytes into a typed numeric value
    int value{255};
    std::cout << "Formatted integer output: " << value << '\n';

    return 0;
}
